package com.rohit.inventory.service;
import com.rohit.inventory.dto.request.*; import com.rohit.inventory.dto.response.MasterDataResponse; import com.rohit.inventory.entity.*; import com.rohit.inventory.exception.*; import com.rohit.inventory.repository.*; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class MasterDataService { private final WarehouseRepository wh; private final WarehouseZoneRepository zones; private final CategoryRepository categories; private final SupplierRepository suppliers; private final ProductRepository products; private final UserRepository users; private final AuditService audit; public MasterDataService(WarehouseRepository wh,WarehouseZoneRepository zones,CategoryRepository categories,SupplierRepository suppliers,ProductRepository products,UserRepository users,AuditService audit){this.wh=wh;this.zones=zones;this.categories=categories;this.suppliers=suppliers;this.products=products;this.users=users;this.audit=audit;}
 @Transactional public MasterDataResponse warehouse(WarehouseRequest r,UUID actor,UUID id){Warehouse x=id==null?new Warehouse():wh.findById(id).orElseThrow(()->new ResourceNotFoundException("Warehouse not found"));if((id==null&&wh.findByCode(r.code()).isPresent())||(id!=null&&wh.findByCode(r.code()).filter(v->!v.getId().equals(id)).isPresent()))throw new DuplicateResourceException("Warehouse code already exists");x.setCode(r.code().toUpperCase());x.setName(r.name());x.setAddressLine1(r.addressLine1());x.setCity(r.city());x.setState(r.state());x.setCountry(r.country()==null?"India":r.country());x.setCapacityQuantity(r.capacityQuantity());if(r.managerUserId()!=null){User m=users.findById(r.managerUserId()).orElseThrow(()->new ResourceNotFoundException("Manager not found"));if(m.getStatus()!=UserStatus.ACTIVE||m.getRoles().stream().noneMatch(role->role.getCode().equals("WAREHOUSE_MANAGER")))throw new IllegalArgumentException("Manager must be an active WAREHOUSE_MANAGER");x.setManager(m);}wh.save(x);audit.record(actor,id==null?"WAREHOUSE_CREATED":"WAREHOUSE_UPDATED","WAREHOUSE",x.getId(),Map.of("code",x.getCode()));return out(x);}
 @Transactional public MasterDataResponse zone(UUID warehouseId,ZoneRequest r,UUID actor,UUID id){Warehouse w=wh.findById(warehouseId).orElseThrow(()->new ResourceNotFoundException("Warehouse not found"));WarehouseZone z=id==null?new WarehouseZone():zones.findById(id).orElseThrow(()->new ResourceNotFoundException("Zone not found"));if((id==null&&zones.findByWarehouseIdAndCode(warehouseId,r.code()).isPresent())||(id!=null&&zones.findByWarehouseIdAndCode(warehouseId,r.code()).filter(v->!v.getId().equals(id)).isPresent()))throw new DuplicateResourceException("Zone code already exists in warehouse");z.setWarehouse(w);z.setCode(r.code().toUpperCase());z.setName(r.name());z.setZoneType(r.zoneType());z.setCapacityQuantity(r.capacityQuantity());zones.save(z);audit.record(actor,id==null?"ZONE_CREATED":"ZONE_UPDATED","WAREHOUSE_ZONE",z.getId(),Map.of("code",z.getCode()));return new MasterDataResponse(z.getId(),z.getCode(),z.getName(),z.getStatus().name(),z.getZoneType(),z.getCapacityQuantity());}
 @Transactional public MasterDataResponse category(CategoryRequest r,UUID actor,UUID id){Category c=id==null?new Category():categories.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found"));Category parent=r.parentCategoryId()==null?null:categories.findById(r.parentCategoryId()).orElseThrow(()->new ResourceNotFoundException("Parent category not found"));if(parent!=null&&(id!=null&&parent.getId().equals(id)))throw new IllegalArgumentException("Category cannot be its own parent");c.setName(r.name());c.setDescription(r.description());c.setParentCategory(parent);categories.save(c);audit.record(actor,id==null?"CATEGORY_CREATED":"CATEGORY_UPDATED","CATEGORY",c.getId(),Map.of("name",c.getName()));return new MasterDataResponse(c.getId(),null,c.getName(),c.getStatus().name(),parent==null?null:parent.getName(),null);}
 @Transactional public MasterDataResponse supplier(SupplierRequest r,UUID actor,UUID id){Supplier s=id==null?new Supplier():suppliers.findById(id).orElseThrow(()->new ResourceNotFoundException("Supplier not found"));if((id==null&&suppliers.findByCode(r.code()).isPresent())||(id!=null&&suppliers.findByCode(r.code()).filter(v->!v.getId().equals(id)).isPresent()))throw new DuplicateResourceException("Supplier code already exists");s.setCode(r.code().toUpperCase());s.setName(r.name());s.setContactName(r.contactName());s.setEmail(r.email());s.setPhone(r.phone());s.setAddressLine1(r.addressLine1());s.setCity(r.city());s.setState(r.state());s.setCountry(r.country()==null?"India":r.country());suppliers.save(s);audit.record(actor,id==null?"SUPPLIER_CREATED":"SUPPLIER_UPDATED","SUPPLIER",s.getId(),Map.of("code",s.getCode()));return new MasterDataResponse(s.getId(),s.getCode(),s.getName(),s.getStatus().name(),s.getEmail(),null);}
@Transactional public MasterDataResponse product(ProductRequest r,UUID actor,UUID id){Product p=id==null?new Product():products.findById(id).orElseThrow(()->new ResourceNotFoundException("Product not found"));if(r.maximumStock().signum()!=0&&r.maximumStock().compareTo(r.reorderLevel())<0)throw new IllegalArgumentException("Maximum stock cannot be below reorder level");if(r.reorderLevel().compareTo(r.minimumStock())<0)throw new IllegalArgumentException("Reorder level cannot be below minimum stock");if((id==null&&products.findBySku(r.sku()).isPresent())||(id!=null&&products.findBySku(r.sku()).filter(v->!v.getId().equals(id)).isPresent()))throw new DuplicateResourceException("Product SKU already exists");if(r.barcode()!=null&&!r.barcode().isBlank()&&((id==null&&products.findByBarcode(r.barcode()).isPresent())||(id!=null&&products.findByBarcode(r.barcode()).filter(v->!v.getId().equals(id)).isPresent())))throw new DuplicateResourceException("Product barcode already exists");p.setSku(r.sku().toUpperCase());p.setName(r.name());p.setDescription(r.description());p.setBarcode(r.barcode());p.setCategory(categories.findById(r.categoryId()).orElseThrow(()->new ResourceNotFoundException("Category not found")));p.setUnitOfMeasure(r.unitOfMeasure().toUpperCase());p.setCostPrice(r.costPrice());p.setSellingPrice(r.sellingPrice());p.setMinimumStock(r.minimumStock());p.setReorderLevel(r.reorderLevel());p.setMaximumStock(r.maximumStock());Set<Supplier> assigned=new HashSet<>();if(r.supplierIds()!=null)for(UUID supplierId:r.supplierIds())assigned.add(suppliers.findById(supplierId).orElseThrow(()->new ResourceNotFoundException("Supplier not found")));p.setSuppliers(assigned);products.save(p);audit.record(actor,id==null?"PRODUCT_CREATED":"PRODUCT_UPDATED","PRODUCT",p.getId(),Map.of("sku",p.getSku()));return productOut(p);}
 @Transactional public MasterDataResponse warehouseStatus(UUID id,WarehouseStatus s,UUID actor){Warehouse w=wh.findById(id).orElseThrow(()->new ResourceNotFoundException("Warehouse not found"));w.setStatus(s);audit.record(actor,"WAREHOUSE_STATUS_CHANGED","WAREHOUSE",id,Map.of("status",s.name()));return out(w);} private MasterDataResponse out(Warehouse w){return new MasterDataResponse(w.getId(),w.getCode(),w.getName(),w.getStatus().name(),w.getCity(),w.getCapacityQuantity());}
@Transactional(readOnly=true) public Page<MasterDataResponse> warehouses(String search,WarehouseStatus status,Pageable page){return wh.search(blank(search),status,page).map(this::out);} @Transactional(readOnly=true) public MasterDataResponse warehouse(UUID id){return out(wh.findById(id).orElseThrow(()->new ResourceNotFoundException("Warehouse not found")));} @Transactional(readOnly=true) public List<MasterDataResponse> zoneList(UUID id){return zones.findByWarehouseId(id).stream().map(z->new MasterDataResponse(z.getId(),z.getCode(),z.getName(),z.getStatus().name(),z.getZoneType(),z.getCapacityQuantity())).toList();} @Transactional(readOnly=true) public List<MasterDataResponse> categories(){return categories.findAll().stream().map(c->new MasterDataResponse(c.getId(),null,c.getName(),c.getStatus().name(),c.getDescription(),null)).toList();} @Transactional(readOnly=true) public List<MasterDataResponse> suppliers(){return suppliers.findAll().stream().map(s->new MasterDataResponse(s.getId(),s.getCode(),s.getName(),s.getStatus().name(),s.getEmail(),null)).toList();} @Transactional(readOnly=true) public Page<MasterDataResponse> products(String search,ProductStatus status,UUID categoryId,UUID supplierId,Pageable page){return products.search(blank(search),status,categoryId,supplierId,page).map(this::productOut);} @Transactional(readOnly=true) public MasterDataResponse product(UUID id){return productOut(products.findById(id).orElseThrow(()->new ResourceNotFoundException("Product not found")));} @Transactional public MasterDataResponse productStatus(UUID id,ProductStatus status,UUID actor){Product p=products.findById(id).orElseThrow(()->new ResourceNotFoundException("Product not found"));p.setStatus(status);audit.record(actor,"PRODUCT_STATUS_CHANGED","PRODUCT",id,Map.of("status",status.name()));return productOut(p);} @Transactional public MasterDataResponse categoryStatus(UUID id,ProductStatus status,UUID actor){Category c=categories.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found"));c.setStatus(status);audit.record(actor,"CATEGORY_STATUS_CHANGED","CATEGORY",id,Map.of("status",status.name()));return new MasterDataResponse(c.getId(),null,c.getName(),c.getStatus().name(),c.getDescription(),null);} @Transactional public MasterDataResponse supplierStatus(UUID id,ProductStatus status,UUID actor){Supplier s=suppliers.findById(id).orElseThrow(()->new ResourceNotFoundException("Supplier not found"));s.setStatus(status);audit.record(actor,"SUPPLIER_STATUS_CHANGED","SUPPLIER",id,Map.of("status",status.name()));return new MasterDataResponse(s.getId(),s.getCode(),s.getName(),s.getStatus().name(),s.getEmail(),null);} private MasterDataResponse productOut(Product p){return new MasterDataResponse(p.getId(),p.getSku(),p.getName(),p.getStatus().name(),p.getCategory().getName(),p.getMaximumStock());} private String blank(String s){return s==null||s.isBlank()?null:s;}
}
